+import { reactive, computed, onUnmounted } from 'vue'
+import { createPiece, randomType, rotateMatrix } from './tetromino'
+
+export const COLS = 10
+export const ROWS = 20
+
+// 计分规则：一次消除 1/2/3/4 行的基础分
+const LINE_SCORES = [0, 100, 300, 500, 800]
+
+function createEmptyBoard() {
+  return Array.from({ length: ROWS }, () => Array(COLS).fill(null))
+}
+
+export function useTetris() {
+  const state = reactive({
+    board: createEmptyBoard(),
+    current: null,
+    next: null,
+    score: 0,
+    lines: 0,
+    level: 1,
+    best: Number(localStorage.getItem('tetris-best') || 0),
+    status: 'ready', // ready | playing | paused | over
+    combo: 0
+  })
+
+  let dropTimer = null
+  let lastDrop = 0

+  // 下落速度随等级加快（毫秒）
+  const dropInterval = computed(() => Math.max(80, 800 - (state.level - 1) * 70))

+  function spawn() {
+    const type = state.next || randomType()
+    state.next = randomType()
+    const piece = createPiece(type)
+    piece.x = Math.floor((COLS - piece.matrix[0].length) / 2)
+    piece.y = 0
+    state.current = piece
+    if (collide(piece, 0, 0)) {
+      gameOver()
+    }
+  }

+  // 碰撞检测：dx/dy 为偏移，matrix 可选（用于旋转预判）
+  function collide(piece, dx, dy, matrix) {
+    const m = matrix || piece.matrix
+    for (let y = 0; y < m.length; y++) {
+      for (let x = 0; x < m[y].length; x++) {
+        if (!m[y][x]) continue
+        const nx = piece.x + x + dx
+        const ny = piece.y + y + dy
+        if (nx < 0 || nx >= COLS || ny >= ROWS) return true
+        if (ny >= 0 && state.board[ny][nx]) return true
+      }
+    }
+    return false
+  }

+  function move(dx) {
+    if (state.status !== 'playing' || !state.current) return
+    if (!collide(state.current, dx, 0)) {
+      state.current.x += dx
+    }
+  }

+  function rotate() {
+    if (state.status !== 'playing' || !state.current) return
+    const rotated = rotateMatrix(state.current.matrix)
+    // 踢墙（wall kick）简单处理：尝试原位、左移、右移
+    const kicks = [0, -1, 1, -2, 2]
+    for (const k of kicks) {
+      if (!collide(state.current, k, 0, rotated)) {
+        state.current.matrix = rotated
+        state.current.x += k
+        return
+      }
+    }
+  }

+  function softDrop() {
+    if (state.status !== 'playing' || !state.current) return
+    if (!collide(state.current, 0, 1)) {
+      state.current.y += 1
+      state.score += 1
+    } else {
+      lock()
+    }
+  }

+  function hardDrop() {
+    if (state.status !== 'playing' || !state.current) return
+    let dropped = 0
+    while (!collide(state.current, 0, 1)) {
+      state.current.y += 1
+      dropped++
+    }
+    state.score += dropped * 2
+    lock()
+  }

+  function lock() {
+    const piece = state.current
+    piece.matrix.forEach((row, y) => {
+      row.forEach((v, x) => {
+        if (v) {
+          const ny = piece.y + y
+          const nx = piece.x + x
+          if (ny >= 0) state.board[ny][nx] = piece.color
+        }
+      })
+    })
+    clearLines()
+    spawn()
+  }

+  function clearLines() {
+    let cleared = 0
+    for (let y = ROWS - 1; y >= 0; y--) {
+      if (state.board[y].every((cell) => cell)) {
+        state.board.splice(y, 1)
+        state.board.unshift(Array(COLS).fill(null))
+        cleared++
+        y++ // 重新检查当前行
+      }
+    }
+    if (cleared > 0) {
+      state.combo++
+      const base = LINE_SCORES[cleared] || 0
+      const comboBonus = state.combo > 1 ? (state.combo - 1) * 50 : 0
+      state.score += (base + comboBonus) * state.level
+      state.lines += cleared
+      state.level = Math.floor(state.lines / 10) + 1
+    } else {
+      state.combo = 0
+    }
+  }

+  function gameOver() {
+    state.status = 'over'
+    if (state.score > state.best) {
+      state.best = state.score
+      localStorage.setItem('tetris-best', String(state.best))
+    }
