+    state.status = 'playing'
+    spawn()
+    startLoop()
+  }

+  function togglePause() {
+    if (state.status === 'playing') {
+      state.status = 'paused'
+      stopLoop()
+    } else if (state.status === 'paused') {
+      state.status = 'playing'
+      startLoop()
+    }
+  }

+  function startLoop() {
+    stopLoop()
+    lastDrop = performance.now()
+    dropTimer = requestAnimationFrame(loop)
+  }

+  function stopLoop() {
+    if (dropTimer) {
+      cancelAnimationFrame(dropTimer)
+      dropTimer = null
+    }
+  }

+  function loop(now) {
+    if (state.status !== 'playing') return
+    if (now - lastDrop >= dropInterval.value) {
+      lastDrop = now
+      if (!collide(state.current, 0, 1)) {
+        state.current.y += 1
+      } else {
+        lock()
+      }
+    }
+    dropTimer = requestAnimationFrame(loop)
+  }

+  // 渲染用：把当前方块叠加到棋盘上
+  const displayBoard = computed(() => {
+    const grid = state.board.map((row) => row.map((c) => (c ? { color: c, active: false } : null)))
+    const piece = state.current
+    if (piece && (state.status === 'playing' || state.status === 'paused')) {
+      piece.matrix.forEach((row, y) => {
+        row.forEach((v, x) => {
+          if (!v) return
+          const ny = piece.y + y
+          const nx = piece.x + x
+          if (ny >= 0 && ny < ROWS && nx >= 0 && nx < COLS) {
+            grid[ny][nx] = { color: piece.color, active: true }
+          }
+        })
+      })
+    }
+    return grid
+  })

