import { COLS, ROWS } from '../game/useTetris'

const props = defineProps({
  board: { type: Array, required: true },
  ghostY: { type: Number, default: -1 },
  current: { type: Object, default: null },
  status: { type: String, default: 'ready' }
})

function cellStyle(cell) {
  if (!cell) return {}
  return {
    background: cell.color,
    boxShadow: `inset 0 0 6px rgba(255,255,255,.45), 0 0 8px ${cell.color}66`
  }
}

// 判断某格是否为幽灵方块
function isGhost(x, y) {
  const p = props.current
  if (!p || props.ghostY < 0 || props.status !== 'playing') return false
  const ly = y - props.ghostY
  const lx = x - p.x
  if (ly < 0 || ly >= p.matrix.length) return false
  if (lx < 0 || lx >= p.matrix[0].length) return false
  return !!p.matrix[ly][lx]
}
</script>

