import { computed } from 'vue'
import { SHAPES } from '../game/tetromino'

const props = defineProps({
  type: { type: String, default: null }
})

const matrix = computed(() => (props.type ? SHAPES[props.type].matrix : null))
const color = computed(() => (props.type ? SHAPES[props.type].color : '#888'))

// 去掉全空的行/列，让预览居中
const trimmed = computed(() => {
  if (!matrix.value) return []
  const m = matrix.value
  const rows = m.filter((r) => r.some((v) => v))
  if (rows.length === 0) return []
  const cols = []
  for (let x = 0; x < m[0].length; x++) {
    if (m.some((r) => r[x])) cols.push(x)
  }
  return rows.map((r) => cols.map((x) => r[x]))
})
</script>

