import { useTetris } from './game/useTetris'

const { state, displayBoard, ghostY, start, move, rotate, softDrop, hardDrop, togglePause } =
  useTetris()

function handleKey(e) {
  const keys = ['ArrowLeft', 'ArrowRight', 'ArrowDown', 'ArrowUp', ' ', 'p', 'P']
  if (keys.includes(e.key)) e.preventDefault()

  if (state.status === 'ready' || state.status === 'over') {
    if (e.key === ' ' || e.key === 'Enter') start()
    return
  }

  switch (e.key) {
    case 'ArrowLeft':
      move(-1)
      break
    case 'ArrowRight':
      move(1)
      break
    case 'ArrowDown':
      softDrop()
      break
    case 'ArrowUp':
      rotate()
      break
    case ' ':
      hardDrop()
      break
    case 'p':
    case 'P':
      togglePause()
      break
  }
}

onMounted(() => window.addEventListener('keydown', handleKey))
onUnmounted(() => window.removeEventListener('keydown', handleKey))
</script>

