            <h2>准备开始</h2>
            <p>按 <b>空格</b> 或 <b>回车</b> 开始游戏</p>
          </template>
          <template v-else-if="state.status === 'paused'">
            <h2>已暂停</h2>
            <p>按 <b>P</b> 继续</p>
